/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars */
import express from "express";
import path from "path";
import cors from "cors";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI, Type } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json({ limit: "50mb" })); // Increase limit for audio base64 uploads

// Model Mapper helper to map requested models to real, supported API IDs
const mapModel = (model: string | undefined): string => {
  if (!model) return "gemini-2.5-flash";
  if (model.includes("gemini-3.5-flash")) return "gemini-2.5-flash";
  if (model.includes("gemini-3.5-pro")) return "gemini-2.5-pro";
  return model;
};

// Response Schemas for structured JSON outputs
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    tim: {
      type: Type.OBJECT,
      properties: {
        abbreviation: { type: Type.STRING },
        name: { type: Type.STRING }
      },
      required: ["abbreviation", "name"]
    },
    summary: { type: Type.STRING },
    dichotomies: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          result: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          justification_pole1: { type: Type.STRING },
          justification_pole2: { type: Type.STRING }
        },
        required: ["name", "result", "confidence", "justification_pole1", "justification_pole2"]
      }
    }
  },
  required: ["tim", "summary", "dichotomies"]
};

const chatSchema = {
  type: Type.OBJECT,
  properties: {
    responseText: { type: Type.STRING },
    suggestedQuestions: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    }
  },
  required: ["responseText", "suggestedQuestions"]
};

// 1. Monologue Typology Analysis Route
app.post("/api/gemini/analyze", async (req, res) => {
  try {
    const { monologue, lockedDichotomies, chatHistory, lockedPsychosophy, audioData, apiKey, model } = req.body;
    
    const keyToUse = apiKey || process.env.GEMINI_API_KEY;
    if (!keyToUse) {
      return res.status(400).json({ error: "API_KEY_MISSING", message: "API key is required. Please provide it in settings or environment." });
    }

    const ai = new GoogleGenAI({
      apiKey: keyToUse.trim(),
      httpOptions: {
        headers: {
          'User-Agent': 'aistudio-build'
        }
      }
    });

    const targetModel = mapModel(model);

    const dichotomiesList = [
      "Рациональность / Иррациональность",
      "Экстраверсия / Интроверсия",
      "Сенсорика / Интуиция",
      "Логика / Этика",
      "Статика / Динамика",
      "Позитивизм / Негативизм",
      "Квестимность / Деклатимность",
      "Тактика / Стратегия",
      "Конструктивизм / Эмотивизм",
      "Процесс / Результат (Правые / Левые)",
      "Уступчивость / Упрямство",
      "Беспечность / Предусмотрительность",
      "Рассудительность / Решительность",
      "Объективизм / Субъективизм (Веселые / Серьезные)",
      "Аристократия / Демократия"
    ].map(d => `- ${d}`).join('\n');

    const prompt = `Ты — профессиональный эксперт по соционике.
ОБЯЗАТЕЛЬНО верни ТОЛЬКО валидный JSON (без разметки markdown), содержащий следующие поля:
1. "tim": объект с полями "abbreviation" (например, "ИЛЭ") и "name" (например, "ИЛЭ (Дон Кихот)")
2. "summary": "Текстовое резюме анализа..."
3. "dichotomies": массив из 15 объектов, каждый из которых представляет ОДНУ из 15 соционических дихотомий (признаков Рейнина). 

Список всех 15 дихотомий, которые ДОЛЖНЫ БЫТЬ в массиве dichotomies:
${dichotomiesList}

Формат объекта дихотомии:
{
  "name": "Название дихотомии (например, Экстраверсия / Интроверсия)",
  "result": "Полюс, который победил (например, Экстраверсия)",
  "confidence": число от 0 до 1 (например, 0.85),
  "justification_pole1": "Почему это похоже на полюс 1...",
  "justification_pole2": "Почему это похоже на полюс 2..."
}

ВНИМАНИЕ: Некоторые соционические признаки заблокированы (зафиксированы) пользователем. Ты ОБЯЗАН подобрать соционический ТИМ и выставить значения дихотомий так, чтобы они СТРОГО соответствовали этим зафиксированным значениям. Ошибки недопустимы. Заблокированные признаки: ${JSON.stringify(lockedDichotomies || {})}
Если есть история чата, учти ее контекст: ${JSON.stringify(chatHistory || [])}

Проанализируй этот текст:
${monologue}`;

    let contents: any = prompt;

    if (audioData) {
      const audioArray = Array.isArray(audioData) ? audioData : [audioData];
      contents = [
        { text: prompt + "\n\nАУДИО-ИНСТРУКЦИЯ (Если применимо): " + (audioArray[0].voicePrompt || 'Анализируй не только текст, но и сам голос, интонации, темп, плавность речи и паузы.') },
        ...audioArray.map((ad: any) => ({ inlineData: { data: ad.base64, mimeType: ad.mimeType } }))
      ];
    }

    const response = await ai.models.generateContent({
      model: targetModel,
      contents: contents,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: 0.2
      }
    });

    res.json(JSON.parse(response.text || "{}"));
  } catch (error: any) {
    console.error("Gemini Analyze Error:", error);
    
    let errorMessage = error.message || "Failed to analyze monologue";
    if (errorMessage.includes("ACCESS_TOKEN_TYPE_UNSUPPORTED") || errorMessage.includes("API_KEY_INVALID") || errorMessage.includes("401") || errorMessage.includes("403")) {
      errorMessage = "Ошибка авторизации API. Убедитесь, что вы ввели правильный API ключ в настройках (или он задан в переменных окружения), и что он имеет доступ к выбранной модели.";
    }
    res.status(500).json({ error: error.name || "Error", message: errorMessage });

  }
});

